/* Music's calculator screen. Font bitmaps are IBM Plex Sans under OFL-1.1,
 * generated by gpSP's tools/ui_font.py; see assets/fonts. */
#include <stdio.h>
#include <string.h>
#include "screen.h"

typedef uint8_t u8;
typedef int8_t s8;
typedef uint16_t u16;
typedef int16_t s16;
struct ui_glyph { u16 bits; s8 x, y; u8 w, h; };
struct ui_kern { u16 pair; s16 adjust; };
struct ui_font {
    const struct ui_glyph *glyphs;
    const u8 *bits;
    const u16 *advance;
    const struct ui_kern *kern;
    u16 kern_count;
    u8 ascent, descent;
};
#include "ui_font.h"

#define RGB(r,g,b) ((u16)((((r)>>3)<<11)|(((g)>>2)<<5)|((b)>>3)))
#define BG RGB(16,21,28)
#define PANEL RGB(29,36,45)
#define TRACK RGB(54,65,76)
#define WHITE RGB(245,247,249)
#define MUTED RGB(169,182,195)
#define GREEN RGB(111,229,180)
#define AMBER RGB(255,185,115)
#define RED RGB(255,142,142)
static u16 *fb;

static void pixel(int x, int y, u16 c)
{
    if ((unsigned)x < SCREEN_W && (unsigned)y < SCREEN_H)
        fb[y * SCREEN_W + x] = c;
}
static void rect(int x, int y, int w, int h, u16 c)
{
    int i, j;
    for (j = y; j < y + h; j++)
        for (i = x; i < x + w; i++) pixel(i, j, c);
}
static void circle(int cx, int cy, int radius, u16 c)
{
    int x, y;
    for (y = -radius; y <= radius; y++)
        for (x = -radius; x <= radius; x++)
            if (x*x + y*y <= radius*radius) pixel(cx+x, cy+y, c);
}
static void roundrect(int x, int y, int w, int h, int r, u16 c)
{
    rect(x+r, y, w-2*r, h, c); rect(x, y+r, w, h-2*r, c);
    circle(x+r, y+r, r, c); circle(x+w-r-1, y+r, r, c);
    circle(x+r, y+h-r-1, r, c); circle(x+w-r-1, y+h-r-1, r, c);
}
static u16 blend(u16 b, u16 f, unsigned a)
{
    unsigned r = (((b>>11)&31)*(15-a) + ((f>>11)&31)*a + 7)/15;
    unsigned g = (((b>>5)&63)*(15-a) + ((f>>5)&63)*a + 7)/15;
    unsigned v = ((b&31)*(15-a) + (f&31)*a + 7)/15;
    return (u16)((r<<11)|(g<<5)|v);
}
static int text(int x, int y, const char *s, const struct ui_font *f, u16 c, int draw)
{
    int pen = x*64, previous = 0;
    for (; *s; s++) {
        unsigned ch = (unsigned char)*s;
        unsigned k;
        int phase, gx, row, col;
        const struct ui_glyph *g;
        if (ch < 32 || ch > 126) ch = '?';
        for (k = 0; k < f->kern_count; k++)
            if (f->kern[k].pair == (unsigned)((previous<<8)|ch)) { pen += f->kern[k].adjust; break; }
        phase = (pen * UI_FONT_PHASES + 32) / 64;
        g = &f->glyphs[ch*UI_FONT_PHASES + phase%UI_FONT_PHASES];
        gx = phase/UI_FONT_PHASES + g->x;
        if (draw) for (row = 0; row < g->h; row++) for (col = 0; col < g->w; col++) {
            unsigned a = (f->bits[g->bits + row*((g->w+1)/2) + col/2] >> (4*(col&1))) & 15;
            int px = gx+col, py = y+g->y+row;
            if (a && (unsigned)px < SCREEN_W && (unsigned)py < SCREEN_H)
                fb[py*SCREEN_W+px] = blend(fb[py*SCREEN_W+px], c, a);
        }
        pen += f->advance[ch]; previous = (int)ch;
    }
    return (pen+32)/64 - x;
}
static void fit(int x, int y, int width, const char *s, const struct ui_font *f, u16 c)
{
    char b[192]; size_t n;
    snprintf(b, sizeof b, "%s", s ? s : "");
    n = strlen(b);
    if (text(0,0,b,f,0,0) > width) {
        while (n && text(0,0,b,f,0,0) > width-12) b[--n] = 0;
        if (n + 3 < sizeof b) strcat(b, "...");
    }
    text(x,y,b,f,c,1);
}
static void center(int x, int y, const char *s, const struct ui_font *f, u16 c)
{
    text(x-text(0,0,s,f,0,0)/2,y,s,f,c,1);
}
static void triangle(int x, int y, int right, u16 c)
{
    int j;
    for (j=-7;j<=7;j++) rect(right ? x : x+(j<0?-j:j), y+j, 8-(j<0?-j:j), 1, c);
}

void screen_render(uint16_t *pixels, const struct music_view *v)
{
    char title[192], artist[192] = "", line[192], time[40];
    char *sep, *split = NULL;
    unsigned i, progress;
    const struct ui_font *large=&ui_font_large, *small=&ui_font_small, *body=&ui_font_body_strong;
    u16 status = v->error ? RED : v->connected ? GREEN : AMBER;
    fb = pixels;
    rect(0,0,320,240,BG);
    text(14,25,"Music",large,WHITE,1);
    circle(83,19,3,status);
    text(92,23,v->connected ? "USB audio" : "USB",small,MUTED,1);
    roundrect(246,8,60,25,6,PANEL);
    center(276,25,"Esc  Exit",small,WHITE);

    /* A deliberate record illustration, independent of song metadata. */
    roundrect(14,43,78,78,10,RGB(202,134,94));
    circle(53,82,30,RGB(40,39,42)); circle(53,82,23,RGB(66,58,59));
    circle(53,82,20,RGB(40,39,42)); circle(53,82,11,AMBER); circle(53,82,3,BG);
    snprintf(title,sizeof title,"%s",v->title ? v->title : "Choose a song");
    sep = strstr(title," - ");
    if (sep) { snprintf(artist,sizeof artist,"%s",sep+3); *sep=0; }
    if (text(0,0,title,large,0,0) > 196) {
        for (i=0; title[i]; i++) if (title[i]==' ') {
            memcpy(line,title,i); line[i]=0;
            if (text(0,0,line,large,0,0)<=196) split=title+i;
        }
    }
    if (split) {
        *split=0; fit(106,65,200,title,large,WHITE);
        fit(106,86,200,split+1,large,WHITE);
    } else fit(106,75,200,title,large,WHITE);
    fit(106,106,200,artist[0] ? artist : "Your music, on your calculator",small,MUTED);
    snprintf(line,sizeof line,"%u / %u",v->count ? v->index+1 : 0,v->count);
    fit(106,123,200,line,small,MUTED);

    fit(14,143,292,v->status,body,status);
    fit(14,160,292,v->detail,small,MUTED);
    progress = v->duration ? (unsigned)((uint64_t)v->elapsed*292/v->duration) : 0;
    if (progress>292) progress=292;
    roundrect(14,171,292,4,1,TRACK);
    if (progress) rect(14,171,(int)progress,4,GREEN);
    snprintf(time,sizeof time,"%u:%02u",v->elapsed/60,v->elapsed%60);
    text(14,191,time,small,MUTED,1);
    snprintf(time,sizeof time,"%u:%02u",v->duration/60,v->duration%60);
    text(306-text(0,0,time,small,0,0),191,time,small,MUTED,1);
    circle(160,198,18,GREEN);
    if (v->playing) { rect(153,191,4,14,BG); rect(163,191,4,14,BG); }
    else triangle(157,198,1,BG);
    triangle(114,198,0,WHITE); rect(111,191,2,14,WHITE);
    triangle(199,198,1,WHITE); rect(209,191,2,14,WHITE);
    snprintf(line,sizeof line,"Vol %u%%",v->volume);
    text(14,215,line,small,MUTED,1);
    text(257,215,v->repeat ? "Loop on" : "Loop off",small,MUTED,1);
    rect(0,225,320,15,PANEL);
    center(160,237,"Enter play / pause    Arrows skip    +/- volume",small,WHITE);
}
